<script setup lang="ts">import {onMounted,ref} from 'vue';import {harnessApi} from '../runtime-client/api';const execution=ref<any[]>([]),capability=ref<any[]>([]),trace=ref('');const load=async()=>{const q=trace.value?`?traceId=${encodeURIComponent(trace.value)}`:'';execution.value=await harnessApi.executions(q);capability.value=await harnessApi.capabilityLogs(q)};onMounted(load);</script>
<template><main class="harness-admin"><h1>Harness Audit</h1><form @submit.prevent="load"><input v-model="trace" placeholder="Trace ID"><button>Filter</button></form><h2>Executions</h2><table><thead><tr><th>Trace</th><th>App/version</th><th>User</th><th>Entry</th><th>Status</th><th>Duration</th></tr></thead><tbody><tr v-for="r in execution" :key="r.id"><td><code>{{r.traceId}}</code></td><td>{{r.appId}} / {{r.appVersionId}}</td><td>{{r.userId}}</td><td>{{r.entryType}}:{{r.entryName}}</td><td>{{r.status}} {{r.errorCode}}</td><td>{{r.elapsedMs}} ms</td></tr></tbody></table><h2>Capability calls</h2><table><thead><tr><th>Trace</th><th>Capability</th><th>Risk</th><th>Status</th><th>Duration</th></tr></thead><tbody><tr v-for="r in capability" :key="r.id"><td><code>{{r.traceId}}</code></td><td>{{r.capabilityName}}@{{r.capabilityVersion}}</td><td>{{r.riskLevel}}</td><td>{{r.status}} {{r.errorCode}}</td><td>{{r.elapsedMs}} ms</td></tr></tbody></table></main></template>
